"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["93970"],{42619(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.ato_do_processo.preliminar_nao_publicado","status":422,"titulo":"O resultado definitivo s\xf3 sai depois do preliminar da mesma mat\xe9ria"},"descricao":{"codigo":"uniplus.selecao.ato_do_processo.preliminar_nao_publicado","requisitos":["UNI-REQ-0157"],"oQueAconteceu":["O item \xe9 um resultado **definitivo**, e o edital declara, para a mesma mat\xe9ria, um resultado\\n**preliminar** que ainda n\xe3o foi publicado. O preliminar abre o ciclo de recurso e o\\ndefinitivo o fecha; publicar o definitivo primeiro encerraria um ciclo que o candidato nem\\nchegou a ver aberto.","A mat\xe9ria \xe9 o tipo de ato: s\xf3 o preliminar do mesmo tipo de ato libera o definitivo. O\\npreliminar publicado de outro tipo de ato n\xe3o o libera, e vale o preliminar da mesma fase ou\\nda fase que abre o ciclo que este definitivo fecha."],"comoResolver":["Publique antes o resultado preliminar da mesma mat\xe9ria, que a consulta dos itens previstos\\naponta como aberto. Com o preliminar publicado, publique o definitivo. O\\nsistema n\xe3o controla ainda o prazo de recurso nem os julgamentos: depois do preliminar, cabe\\na quem publica esperar o encerramento do prazo e o julgamento dos recursos antes de publicar\\no definitivo."],"ondeAparece":["Publica\xe7\xe3o de item do edital"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Ato do processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);